    <script>
      function SafeGetValue(obj, path, defaultValue = 'N/A') {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
          if (
            current === undefined ||
            current === null ||
            typeof current !== 'object' ||
            !current.hasOwnProperty(keys[i])
          ) {
            return defaultValue;
          }
          current = current[keys[i]];
        }
        if (current === undefined || current === null) {
          return defaultValue;
        }
        if (Array.isArray(current)) {
          if (current.length > 0) {
            const actualValue = current[0];
            if (typeof actualValue === 'boolean') {
              return actualValue;
            }
            return String(actualValue);
          } else {
            return defaultValue;
          }
        }
        if (typeof current === 'boolean') {
          return current;
        }
        return String(current);
      }

      function GetRawValue(obj, path, defaultValue = null) {
        const keys = Array.isArray(path) ? path : path.split('.');
        let cur = obj;
        for (let i = 0; i < keys.length; i++) {
          if (!cur || typeof cur !== 'object' || !(keys[i] in cur)) return defaultValue;
          cur = cur[keys[i]];
        }
        return cur === undefined ? defaultValue : cur;
      }

      function updateTextField(elementId, value) {
        const el = document.getElementById(elementId);
        if (el) {
          el.innerText = value === undefined || value === null ? 'N/A' : String(value);
        }
      }

      function updateProgressBar(barId, valueMainId, valueDescId, rawValue, min, max) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        if (!valueMainDisplay) return;

        const displayText = rawValue === undefined || rawValue === null ? String(min) : String(rawValue);
        valueMainDisplay.innerText = displayText;

        let numericValue = min;
        if (typeof rawValue === 'number') {
          numericValue = rawValue;
        } else if (typeof rawValue === 'string') {
          const m = rawValue.match(/-?\d+(?:\.\d+)?/);
          if (m) numericValue = parseFloat(m[0]);
        } else if (!isNaN(Number(rawValue))) {
          numericValue = Number(rawValue);
        }

        if (progressBar) {
          numericValue = Math.max(min, Math.min(max, numericValue));
          const range = max - min;
          const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
          progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        }
      }

      function updatePersonnelList(personnelObj) {
        const container = document.getElementById('personnel-list');
        if (!container) return;

        if (!personnelObj || typeof personnelObj !== 'object' || Object.keys(personnelObj).length === 0) {
          container.innerHTML = '<div class="value-main" style="text-align: center; opacity: 0.6;">暂无人员</div>';
          return;
        }

        let html = '';
        for (const [id, person] of Object.entries(personnelObj)) {
          if (!person || typeof person !== 'object') continue;

          const name = person['名称'] || 'N/A';
          const intro = person['人物简介'] || 'N/A';
          const appearance = person['外貌描述'] || 'N/A';
          const outfit = person['穿着'] || 'N/A';
          const status = person['当前状态'] || 'N/A';

          html += `
            <div class="commission-item">
              <div class="commission-title">${name}</div>
              <div class="commission-field">简介: <span>${intro}</span></div>
              <div class="commission-field">外貌: <span>${appearance}</span></div>
              <div class="commission-field">穿着: <span>${outfit}</span></div>
              <div class="commission-field">状态: <span>${status}</span></div>
            </div>
          `;
        }
        container.innerHTML = html;
      }

      function updateCommissionList(commissionsObj) {
        const container = document.getElementById('commission-list');
        if (!container) return;

        if (!commissionsObj || typeof commissionsObj !== 'object' || Object.keys(commissionsObj).length === 0) {
          container.innerHTML = '<div class="value-main" style="text-align: center; opacity: 0.6;">暂无委托</div>';
          return;
        }

        let html = '';
        for (const [id, commission] of Object.entries(commissionsObj)) {
          if (!commission || typeof commission !== 'object') continue;

          const name = commission['委托名'] || 'N/A';
          const client = commission['委托方'] || 'N/A';
          const content = commission['委托内容'] || 'N/A';
          const status = commission['委托状态'] || '未知';

          html += `
            <div class="commission-item">
              <div class="commission-title">${name}</div>
              <div class="commission-field">委托方: <span>${client}</span></div>
              <div class="commission-field">内容: <span>${content}</span></div>
              <div class="commission-field">状态: <span>${status}</span></div>
            </div>
          `;
        }
        container.innerHTML = html;
      }

      async function initDisplay() {
        try {
          const messages = await getChatMessages(getCurrentMessageId());
          if (!messages || messages.length === 0 || !messages[0].data) {
            document.getElementById('status-card').innerHTML =
              "<p style='color:var(--accent-soft); padding:10px; text-align:center;'>无法加载状态数据</p>";
            return;
          }
          const gameData = messages[0].data;
          const characterData = gameData.stat_data;
          if (!characterData) {
            document.getElementById('status-card').innerHTML =
              "<p style='color:var(--accent-soft); padding:10px; text-align:center;'>数据缺失</p>";
            return;
          }

          // 世界信息
          updateTextField('world-date', SafeGetValue(characterData, '世界信息.当前日期'));
          updateTextField('world-time', SafeGetValue(characterData, '世界信息.当前时间'));
          updateTextField('world-location', SafeGetValue(characterData, '世界信息.当前地点'));

          // 夜的信息
          updateTextField('yoru-pose', SafeGetValue(characterData, '夜.当前状态.姿势'));
          updateTextField('yoru-action', SafeGetValue(characterData, '夜.当前状态.正在做的事情'));
          updateTextField('yoru-outfit', SafeGetValue(characterData, '夜.当前着装'));
          updateTextField('yoru-thought', SafeGetValue(characterData, '夜.当前想法'));
          updateTextField('yoru-experience', SafeGetValue(characterData, '夜.性经验次数'));

          // 人员信息
          updatePersonnelList(GetRawValue(characterData, '人员', {}));

          // 委托信息
          updateCommissionList(GetRawValue(characterData, '委托', {}));

          switchTab('world');
        } catch (error) {
          document.getElementById('status-card').innerHTML =
            `<p style='color:var(--accent-soft); padding:10px; text-align:center;'>加载出错: ${error.message}</p>`;
        }
      }

      function switchTab(tabId) {
        const contents = document.querySelectorAll('.tab-content');
        contents.forEach(content => {
          content.style.display = 'none';
        });

        const buttons = document.querySelectorAll('.tab-button');
        buttons.forEach(button => {
          button.classList.remove('active');
        });

        const selectedContent = document.getElementById('tab-' + tabId);
        if (selectedContent) {
          selectedContent.style.display = 'block';
        }

        const selectedButton = document.getElementById('btn-' + tabId);
        if (selectedButton) {
          selectedButton.classList.add('active');
        }
      }

      document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
